(function(){
var RAW=Uint8Array.from(atob(""),function(c){return c.charCodeAt(0)})
,SZL=28,N=RAW.length/SZL,LB=[];
for(var i=0;i<N;i++){var t=RAW[i*SZL],id=RAW[i*SZL+2]|(RAW[i*SZL+3]<<8);LB.push({i:i,t:t,id:id,n:eqName(t,id)})}
var ARMT=[5,1,2,3,4],KN={B:"Sword",G:"Gunner","":"Lainnya"},GR=/^(X|Z|S|U|G|GX)$/;
function lw(n){var w=bn(n).split(" ");while(w.length>1&&GR.test(w[w.length-1]))w.pop();return w[w.length-1].toLowerCase()}
// tabel dari database set armor: nama potongan -> set, kata akhir -> Sword/Gunner
var AN={},KW={};
ARS.forEach(function(s,si){for(var k=0;k<5;k++){var n=s[2][k];if(!n)continue;var key=ARTY[k]+"|"+n.toLowerCase();if(AN[key]===undefined)AN[key]=si;
 if(s[1]==="B"||s[1]==="G"){var kk=ARTY[k]+"|"+lw(n),o=KW[kk]||(KW[kk]={B:0,G:0});o[s[1]]++}}});
function kw(t,n){var w=lw(n),o=KW[t+"|"+w];if(o)return o;for(var k in KW){if(k.indexOf(t+"|")!==0)continue;var u=k.slice(2);if(u.length>=4&&w.length>u.length&&w.slice(-u.length)===u)return KW[k]}return null}
function derive(p){var a=p.map(function(x){return bn(x.n)}),pre=a[0];a.forEach(function(s){while(s.indexOf(pre)!==0)pre=pre.slice(0,-1)});pre=pre.replace(/\s+$/,"");
 var g=a.map(function(s){var w=s.split(" ");return w[w.length-1]}),gr=GR.test(g[0])&&g.every(function(x){return x===g[0]})?g[0]:"";
 if(pre.length<3)pre=a[0].split(" ")[0];return pre+(gr?" "+gr:"")}
function sig(p){var o=[];p.forEach(function(x){o.push(Array.prototype.join.call(RAW.subarray(x.i*SZL,x.i*SZL+SZL),","))});return o.join("|")}
function mk(p){var cnt={},kv={B:0,G:0},best=-1,bc=0,kind="",name="";
 p.forEach(function(x){var si=AN[x.t+"|"+bn(x.n).toLowerCase()];if(si!==undefined)cnt[si]=(cnt[si]||0)+1;var w=kw(x.t,x.n);if(w){if(w.B>w.G)kv.B++;else if(w.G>w.B)kv.G++}});
 for(var s in cnt)if(cnt[s]>bc){bc=cnt[s];best=+s}
 if(best>=0&&bc>=3){kind=ARS[best][1];name=ARS[best][0].length<3?derive(p):ARS[best][0]}else{kind=kv.B>kv.G?"B":kv.G>kv.B?"G":"";name=derive(p)}
 return{p:p,kind:kind,name:name,sig:sig(p),n:1}}
var armor=LB.filter(function(x){return x.t>=1&&x.t<=5}),SETS=[],ORPH=[],seen={};
for(var k=0;k<armor.length;){var ok=k+5<=armor.length;for(var j=0;ok&&j<5;j++)if(armor[k+j].t!==ARMT[j])ok=false;
 if(ok){var st=mk(armor.slice(k,k+5));if(seen[st.sig])seen[st.sig].n++;else{seen[st.sig]=st;SETS.push(st)}k+=5}else{ORPH.push(armor[k]);k++}}
// nama kembar (nama+tipe sama tapi isi beda): bedakan lewat kata akhir kepala, lalu nomor
var grp={};SETS.forEach(function(s){var key=s.name+"|"+s.kind;(grp[key]=grp[key]||[]).push(s)});
function hw(s){var w=bn(s.p[0].n).split(" ");return w[w.length>1&&GR.test(w[w.length-1])?w.length-2:w.length-1]}
Object.keys(grp).forEach(function(key){var g=grp[key];if(g.length<2)return;var d={};g.forEach(function(s){d[hw(s)]=1});
 g.forEach(function(s){if(Object.keys(d).length>1)s.name+=" ["+hw(s)+"]"});var h={};g.forEach(function(s){h[s.name]=(h[s.name]||0)+1});
 g.forEach(function(s){if(h[s.name]>1)s.name+=" · ID "+s.p[0].id})});
var WEAP=LB.filter(function(x){return x.t>=7}),OTH=LB.filter(function(x){return x.t===6}).concat(ORPH);OTH.sort(function(a,b){return a.i-b.i});
var wt={};WEAP.forEach(function(x){wt[x.t]=1});
$("elwt").innerHTML='<option value="">Semua senjata</option>'+Object.keys(wt).map(Number).sort(function(a,b){return a-b}).map(function(t){return'<option value="'+t+'">'+eqTypeName(t)+"</option>"}).join("");
function btn(a,i){return'<button class="g" data-'+a+'="'+i+'" style="margin:0;flex:1" type="button">+ Tambah</button>'}
function one(x){return'<div class="r" style="align-items:center;margin:3px 0"><div style="flex:3;font-size:14px">'+eqIi(x.t,x.id)+esc(x.n)+'<br><small class="wr">'+esc(eqTypeName(x.t))+" · ID "+x.id+"</small></div>"+btn("lib",x.i)+"</div>"}
function list(arr,q,ft,box,info){var o=[],n=0;q=q.trim().toLowerCase();
 arr.forEach(function(x){if(ft&&String(x.t)!==ft)return;if(q&&(x.n.toLowerCase()+" "+eqTypeName(x.t).toLowerCase()).indexOf(q)<0)return;n++;if(o.length<80)o.push(one(x))});
 $(box).innerHTML=o.join("")||'<p class="wr">Tidak ada hasil.</p>';$(info).textContent=n>80?n+" hasil, tampil 80. Persempit pencarian.":n+" hasil."}
function drawSet(){var q=$("elq").value.trim().toLowerCase(),f=$("elk").value,o=[],n=0;
 SETS.forEach(function(s,i){if(f&&(s.kind||"-")!==f)return;if(q&&(s.name+" "+s.p.map(function(x){return x.n}).join(" ")).toLowerCase().indexOf(q)<0)return;n++;
  o.push('<div class="r" style="align-items:center;margin:4px 0"><div style="flex:3;font-size:14px">'+eqIi(5,s.p[0].id)+"<b>"+esc(s.name)+'</b> <small class="wr">· '+KN[s.kind]+(s.n>1?" · "+s.n+" salinan sama":"")+'</small><br><small class="wr">'+s.p.map(function(x){return esc(x.n)}).join(" · ")+'</small><br><small class="wr">ID '+s.p.map(function(x){return x.id}).join(" · ")+"</small></div>"+btn("set",i)+"</div>")});
 $("elres").innerHTML=o.join("")||'<p class="wr">Tidak ada preset.</p>';$("elinfo").textContent=n+" preset set armor (5 bagian per set)."}
function drawW(){list(WEAP,$("elwq").value,$("elwt").value,"elwres","elwinfo")}
function drawO(){list(OTH,$("elo").value,"","elores","eloinfo")}
function need(){if(typeof S==="undefined"||!S){alert("Pilih file save dulu");return false}return true}
function free(n){var f=[];for(var k=0;k<EQCOUNT&&f.length<n;k++){var e=eqView(k);if(!e.type&&!e.id)f.push(k)}return f}
function put(i,slot){var v=dv();for(var j=0;j<SZL;j++)v.setUint8(EQBASE+slot*SZL+j,RAW[i*SZL+j])}
function add(i,info){if(!need())return;var f=free(1);if(!f.length){alert("Equipment Box penuh (tidak ada slot kosong).");return}put(i,f[0]);mark(true);eqDraw();$(info).textContent="Ditambahkan ke slot "+(f[0]+1)+": "+LB[i].n}
function addSet(i){if(!need())return;var s=SETS[i],f=free(5);if(f.length<5){alert("Slot equipment kosong tidak cukup (butuh 5, ada "+f.length+").");return}
 var done=[];s.p.forEach(function(x,j){put(x.i,f[j]);done.push({t:x.t,slot:f[j]})});if($("elwear").value==="1")arWear(done);
 mark(true);eqDraw();$("elinfo").textContent="Set ditambahkan ke slot "+f.map(function(x){return x+1}).join(", ")+": "+s.name+" ("+KN[s.kind]+")"}
$("elq").oninput=drawSet;$("elk").onchange=drawSet;$("elwq").oninput=drawW;$("elwt").onchange=drawW;$("elo").oninput=drawO;
$("elres").onclick=function(e){var b=e.target.closest("button[data-set]");if(b)addSet(+b.dataset.set)};
$("elwres").onclick=function(e){var b=e.target.closest("button[data-lib]");if(b)add(+b.dataset.lib,"elwinfo")};
$("elores").onclick=function(e){var b=e.target.closest("button[data-lib]");if(b)add(+b.dataset.lib,"eloinfo")};
$("eltabs").onclick=function(e){var b=e.target.closest("button[data-tab]");if(!b)return;["set","wp","ot"].forEach(function(t){$("elp_"+t).style.display=t===b.dataset.tab?"":"none"});
 Array.prototype.forEach.call($("eltabs").children,function(x){x.setAttribute("aria-pressed",x===b?"true":"false")})};
drawSet();drawW();drawO()})();
